import React from "react";
import { motion } from "framer-motion";
import { TESTIMONIALS } from "./Content";
import { Quote, Star } from "lucide-react";

export default function Testimonials() {
  return (
    <section id="reviews" className="section" style={{ background: "#fff" }}>
      <div className="container mx-auto">
        {/* Header */}
        <motion.div
          className="mb-10"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="flex items-center gap-3 mb-4">
            <div className="w-8 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="overline">Testimonials</span>
          </div>
          <h2 className="section-title">
            What decorators across India <span>keep saying</span>.
          </h2>
        </motion.div>

        {/* Testimonials Grid - Mobile Responsive */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {TESTIMONIALS.map((t, i) => (
            <motion.div
              key={i}
              className="testimonial-card"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1, duration: 0.5 }}
              whileHover={{ y: -4 }}
            >
              <Quote size={24} color="#d4af37" className="mb-4" strokeWidth={1.5} />
              <p className="serif text-sm mb-4" style={{ color: "#1a080a", lineHeight: 1.6 }}>
                "{t.quote}"
              </p>
              <div className="flex items-center gap-1 mb-2">
                {[...Array(5)].map((_, idx) => (
                  <Star key={idx} size={14} fill="#d4af37" color="#d4af37" strokeWidth={0} />
                ))}
              </div>
              <div className="font-semibold text-sm" style={{ color: "#1a080a" }}>{t.name}</div>
              <div className="text-xs mt-1" style={{ color: "rgba(26,8,10,0.6)" }}>{t.role} - {t.city}</div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
